$json.body.entry?.[0]?.changes ? 
  (
    // Comparar ID del que escribe (from.id) con TU ID de cuenta (entry.id)
    // Si son iguales, devuelve TRUE (BLOQUEAR). Si son distintos, FALSE (PASAR).
