  ) 
: 

// 2. LÓGICA PARA MENSAJES PRIVADOS (DM)
($json.body.entry?.[0]?.messaging?.[0] ? 
  (
    // Bloquear si es estado de entrega, lectura o mensaje propio (echo)
    !!$json.body.entry[0].messaging[0].delivery || 
    !!$json.body.entry[0].messaging[0].read || 
    !!$json.body.entry[0].messaging[0].message?.is_echo ||
    !$json.body.entry[0].messaging[0].message?.text
  ) 
  : true // Si no es ni comentario ni DM conocido -> BLOQUEAR (True)
)
}}

