const records = items;
const now = new Date();
const VENTANA_HORAS = 2;

// Si por alguna razón la consulta viene vacía, permitimos responder por seguridad
if (!records || records.length <= 1) {
  return [{
    json: {
      can_respond: true,
      reason: "No se encontraron registros previos. Responder disponible.",
      hours_remaining: 0
    }
  }];
}

/**
 * 1. ORDENAMIENTO
 * Ordenamos para asegurar que el índice [0] sea siempre el más reciente
 */
const sortedRecords = [...records].sort((a, b) => 
  new Date(b.json.created_at) - new Date(a.json.created_at)
);

const lastRecord = sortedRecords[0].json;
const lastResponseDate = new Date(lastRecord.created_at);

// Cálculo de tiempo transcurrido
const diffMs = now - lastResponseDate;
const hoursElapsed = diffMs / (1000 * 60 * 60);
const minutesElapsed = diffMs / (1000 * 60);

// Cálculo de tiempo restante
const hoursRemaining = Math.max(0, VENTANA_HORAS - hoursElapsed);
const minutesRemaining = Math.max(0, (VENTANA_HORAS * 60) - minutesElapsed);

let canRespond = false;
let reason = "";

/**
 * 2. VALIDACIÓN DE VENTANA
 */
if (hoursElapsed >= VENTANA_HORAS) {
    canRespond = true;
    reason = `Permitido: Han pasado ${hoursElapsed.toFixed(2)}h.`;
} else {
    canRespond = false;
    reason = `Bloqueado: Re-contacto muy pronto. Faltan ${minutesRemaining.toFixed(0)} minutos para cumplir las 2h.`;
}

return [{
  json: {
    can_respond: canRespond,
    reason: reason,
    last_contact: lastRecord.created_at,
    hours_elapsed: hoursElapsed.toFixed(2),
    minutes_remaining: minutesRemaining.toFixed(0),
    total_messages_analizados: records.length
  }
}];

const saldo = $('trae saldo').first().json;
const planType = (saldo.plan_type || 'free').toLowerCase();
const puedeAgendar = saldo.scheduling_enabled === true;

// Los servicios vienen del nodo HTTP Request anterior
const inputItems = $('Traer Servicios').all();
const servicios = inputItems.map(item => item.json);

let serviciosTexto = '';

if (servicios.length > 0) {
  const lineas = servicios.map(s => {
    let linea = `- ${s.name}`;
    if (s.price) linea += `: $${Number(s.price).toLocaleString('es-CL')}`;
    if (s.duration_minutes && s.duration_minutes > 0) linea += ` (${s.duration_minutes} min)`;
    if (s.description) linea += ` — ${s.description}`;
    return linea;
  });

  serviciosTexto = '\n\nServicios disponibles del negocio:\n' + lineas.join('\n');

  if (puedeAgendar) {
    serviciosTexto += '\n\nINSTRUCCIÓN DE AGENDAMIENTO: Este negocio tiene agendamiento activo. Si el cliente quiere agendar una cita para cualquiera de estos servicios, usa la herramienta "Call Tool - Agendador" para buscar disponibilidad y crear la cita.';
  } else {
    serviciosTexto += '\n\nNOTA: Este negocio NO tiene agendamiento automático. Si el cliente quiere agendar, indícale que contacte directamente al negocio para coordinar una hora.';
  }
}

return [{
  json: {
    ...($input.first().json),
    servicios_texto: serviciosTexto,
    plan_type: planType,
    puede_agendar: puedeAgendar,
    cantidad_servicios: servicios.length
  }
}];
